class ListaSarcini:
    def __init__(self):
        self.de_facut = []
        self.facute = []

    def adauga(self, sarcina):
        self.de_facut.append(sarcina)

    def bifeaza(self, sarcina):
        self.de_facut.remove(sarcina)
        self.facute.append(sarcina)

lista = ListaSarcini()
for s in ["cumpărături", "teme", "sport"]:
    lista.adauga(s)
lista.bifeaza("teme")
print(lista.de_facut)

