class ContBancar:
    def __init__(self, titular, sold):
        self.titular = titular
        self.sold = sold

    def transfera(self, alt_cont, suma):
        if suma <= self.sold:
            self.sold -= suma
            alt_cont.sold += suma

ana = ContBancar("Ana", 300)
radu = ContBancar("Radu", 100)
ana.transfera(radu, 120)
print(ana.sold, radu.sold)

class Carte:
    def __init__(self, titlu, pret):
        self.titlu = titlu
        self.pret = pret

class Librarie:
    def __init__(self):
        self.carti = []

    def adauga(self, carte):
        self.carti.append(carte)

    def valoare_totala(self):
        return sum(c.pret for c in self.carti)

    def cea_mai_scumpa(self):
        return max(self.carti, key=lambda c: c.pret).titlu

l = Librarie()
l.adauga(Carte("Ion", 45))
l.adauga(Carte("Baltagul", 30))
l.adauga(Carte("Maitreyi", 52))
print(l.valoare_totala())
print(l.cea_mai_scumpa())

